"use client";

import { FormEvent, useEffect, useState } from "react";

type Summary = { exists: boolean; records: Record<string, number> };
type CaptureKind = "event" | "application" | "playlist" | "reference" | "work-update" | "travel" | "idea";
type CaptureStatus = "happened" | "planned" | "applied" | "not-selected" | "in-progress" | "uncertain";
type SearchResult = { id: string; kind: string; score: number; matchedTerms: string[]; snippet: string };
type EvidencePack = { evidence: Array<{ id: string; kind: string; authority: string; matchedTerms: string[]; snippet: string }>; connectionCandidates: Array<{ fromId: string; toId: string; detail: string }>; notice: string };
type PrivateSource = "spotify-history" | "google-timeline" | "echoes-export" | "editor-cut";
type SpotifyStatus = { configured: boolean; authorised: boolean; permissions: string[]; baselinePlaylistLinks?: string[] };
type LastFmStatus = { configured: boolean; mode: string };
type ImportMarkers = { calendarPrepared: boolean; mapsPrepared: boolean; mapsListPrepared: boolean; timelinePrepared: boolean; youtubePrepared: boolean; lastFmHistory: boolean; sideQuestControlRoom: boolean };
type SpotifySelection = { recentlyPlayedCount: number; libraryPlaylistCount: number; recommendations: Array<{ id: string; name: string; tracksTotal: number; recentPlayOverlap: number; recentContextPlays?: number; coverImageUrl?: string; spotifyUrl?: string }>; selectionBasis: "recent-play-context" | "owned" | "owned-collaborative" | "library-fallback" | "explicit-baseline" | "none" };
type SpotifyPreviewResult = { tone: "success" | "error"; text: string };
type EditorialCandidate = { id: string; label: string; modifiedAt: string; bytes: number };
type VaultSession = { active: boolean; expiresAt?: string };

async function vaultRequest(payload: Record<string, unknown>) {
  const { passphrase, ...rest } = payload;
  const body = typeof passphrase === "string" && passphrase ? { ...rest, passphrase } : rest;
  const response = await fetch("/api/vault", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });
  const result = await response.json() as { error?: string; summary?: Summary; migration?: { moments: number }; import?: { retained: number; total: number; sources?: Array<{ source: string; retained: number; total: number }>; pagination?: { pagesRead: number; totalPages: number; complete: boolean } }; editorCut?: { createdRecords: number }; editorialDraft?: { id: string; title: string; wordCount: number }; editorialCandidates?: EditorialCandidate[]; evidencePack?: EvidencePack; results?: SearchResult[] };
  if (!response.ok || result.error) throw new Error(result.error ?? "The local Vault did not accept that request.");
  return result;
}

export function PrivateVault() {
  const [exists, setExists] = useState<boolean>(); const [passphrase, setPassphrase] = useState(""); const [summary, setSummary] = useState<Summary>(); const [session, setSession] = useState<VaultSession>({ active: false }); const [message, setMessage] = useState("The Vault is local-only. Its passphrase is never stored by the browser."); const [busy, setBusy] = useState(false); const [importMarkers, setImportMarkers] = useState<ImportMarkers>();
  const [title, setTitle] = useState(""); const [kind, setKind] = useState<CaptureKind>("event"); const [status, setStatus] = useState<CaptureStatus>("uncertain"); const [when, setWhen] = useState(""); const [evidence, setEvidence] = useState(""); const [threads, setThreads] = useState(""); const [query, setQuery] = useState(""); const [results, setResults] = useState<SearchResult[]>([]); const [evidencePack, setEvidencePack] = useState<EvidencePack>(); const [sideQuestFile, setSideQuestFile] = useState<File>(); const [sideQuestResult, setSideQuestResult] = useState<string>(); const [source, setSource] = useState<PrivateSource>("spotify-history"); const [sourceFiles, setSourceFiles] = useState<File[]>([]); const [sourceConsent, setSourceConsent] = useState(false); const [spotify, setSpotify] = useState<SpotifyStatus>(); const [spotifySelection, setSpotifySelection] = useState<SpotifySelection>(); const [selectedPlaylists, setSelectedPlaylists] = useState<string[]>([]); const [baselinePlaylistLinks, setBaselinePlaylistLinks] = useState(""); const [spotifyPreviewing, setSpotifyPreviewing] = useState(false); const [spotifyPreviewMode, setSpotifyPreviewMode] = useState<"explicit" | "recent">(); const [spotifyPreviewResult, setSpotifyPreviewResult] = useState<SpotifyPreviewResult>(); const [spotifyImporting, setSpotifyImporting] = useState(false); const [lastFm, setLastFm] = useState<LastFmStatus>(); const [lastFmUsername, setLastFmUsername] = useState(""); const [lastFmFrom, setLastFmFrom] = useState("2026-07-01"); const [lastFmTo, setLastFmTo] = useState("2026-08-26"); const [lastFmConsent, setLastFmConsent] = useState(false); const [lastFmResult, setLastFmResult] = useState<string>(); const [lastFmImporting, setLastFmImporting] = useState(false); const [preparedTakeoutImported, setPreparedTakeoutImported] = useState<number>(); const [preparedTakeoutImporting, setPreparedTakeoutImporting] = useState(false); const [preparedTakeoutResult, setPreparedTakeoutResult] = useState<SpotifyPreviewResult>(); const [preparedSelectedMapsImporting, setPreparedSelectedMapsImporting] = useState(false); const [preparedSelectedMapsResult, setPreparedSelectedMapsResult] = useState<SpotifyPreviewResult>(); const [mapsListUrl, setMapsListUrl] = useState(""); const [mapsListFile, setMapsListFile] = useState<File>(); const [mapsListConsent, setMapsListConsent] = useState(false); const [mapsListImporting, setMapsListImporting] = useState(false); const [mapsListResult, setMapsListResult] = useState<SpotifyPreviewResult>(); const [editorialCandidates, setEditorialCandidates] = useState<EditorialCandidate[]>([]); const [editorialDraftId, setEditorialDraftId] = useState(""); const [editorialDraftConsent, setEditorialDraftConsent] = useState(false); const [editorialDraftResult, setEditorialDraftResult] = useState<SpotifyPreviewResult>();
  async function refreshEditorialCandidates() { try { const result = await vaultRequest({ action: "list-private-editorial-candidates", passphrase }); const candidates = result.editorialCandidates ?? []; setEditorialCandidates(candidates); setEditorialDraftId((current) => candidates.some((candidate) => candidate.id === current) ? current : candidates[0]?.id ?? ""); } catch (error) { setEditorialDraftResult({ tone: "error", text: error instanceof Error ? error.message : "The private editorial candidates could not be read." }); } }
  useEffect(() => { fetch("/api/vault", { cache: "no-store" }).then((response) => response.json()).then((result: { exists: boolean; imports?: ImportMarkers; session?: VaultSession }) => { setExists(result.exists); setImportMarkers(result.imports); setSession(result.session ?? { active: false }); }).catch(() => setMessage("The Vault status could not be read.")); fetch("/api/connectors/spotify", { cache: "no-store" }).then((response) => response.json()).then((result: SpotifyStatus) => { setSpotify(result); if (result.baselinePlaylistLinks?.length) setBaselinePlaylistLinks(result.baselinePlaylistLinks.join("\n")); }).catch(() => setSpotify({ configured: false, authorised: false, permissions: [] })); fetch("/api/connectors/lastfm", { cache: "no-store" }).then((response) => response.json()).then(setLastFm).catch(() => setLastFm({ configured: false, mode: "selected-window-only" })); fetch("/api/connectors/google-maps-list", { cache: "no-store" }).then((response) => response.json()).then((result: { configured?: boolean; url?: string }) => { if (result.configured && result.url) setMapsListUrl(result.url); }).catch(() => undefined); }, []);
  async function run(action: "initialise" | "unlock" | "migrate-recovery") { setBusy(true); try { const result = await vaultRequest({ action, passphrase }) as { summary?: Summary; migration?: { moments: number }; session?: VaultSession }; setExists(true); if (result.summary) setSummary(result.summary); if (result.session) setSession(result.session); if (action === "unlock") void refreshEditorialCandidates(); if (action !== "migrate-recovery") setPassphrase(""); setMessage(action === "initialise" ? "Encrypted Vault created and unlocked locally." : action === "migrate-recovery" ? `Synced ${result.migration?.moments ?? 0} preserved Moment records. Other Vault records were not altered.` : `Vault unlocked across this browser until ${result.session?.expiresAt ? new Date(result.session.expiresAt).toLocaleTimeString() : "the fixed session expiry"}.`); } catch (error) { setMessage(error instanceof Error ? error.message : "The Vault request failed."); } finally { setBusy(false); } }
  async function lockSession() { setBusy(true); try { await vaultRequest({ action: "lock-session" }); setSession({ active: false }); setSummary(undefined); setEditorialCandidates([]); setMessage("Vault session locked across this browser. Unlock again to work with private evidence."); } catch (error) { setMessage(error instanceof Error ? error.message : "The Vault session could not be locked."); } finally { setBusy(false); } }
  async function capture(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setBusy(true); try { const result = await vaultRequest({ action: "capture", passphrase, capture: { title, kind, status, when, evidence, threads: threads.split(",").map((item) => item.trim()).filter(Boolean) } }); setSummary(result.summary); setTitle(""); setWhen(""); setEvidence(""); setThreads(""); setMessage("Captured as private, pending, non-canonical evidence. No relationship or meaning was inferred."); } catch (error) { setMessage(error instanceof Error ? error.message : "The capture could not be saved."); } finally { setBusy(false); } }
  async function search(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setBusy(true); try { const result = await vaultRequest({ action: "search", passphrase, query }); setResults(result.results ?? []); setMessage(`Retrieved ${(result.results ?? []).length} local evidence record(s). Retrieval is not an editorial decision.`); } catch (error) { setMessage(error instanceof Error ? error.message : "The Vault search could not run."); } finally { setBusy(false); } }
  async function buildEvidencePack(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setBusy(true); try { const result = await vaultRequest({ action: "build-evidence-pack", passphrase, query }); setEvidencePack(result.evidencePack); setMessage(`Built a local evidence packet from ${result.evidencePack?.evidence.length ?? 0} record(s). No external model was called and nothing was promoted to fact.`); } catch (error) { setMessage(error instanceof Error ? error.message : "The local evidence packet could not be built."); } finally { setBusy(false); } }
  async function importPrivateSource(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!sourceFiles.length || !sourceConsent) return; setBusy(true); try { if (sourceFiles.some((file) => file.size > 12_000_000)) throw new Error("Choose files smaller than 12 MB each for the browser import. Larger exports can still use the local CLI minimiser."); const contents = await Promise.all(sourceFiles.map((file) => file.text())); const content = source === "editor-cut" ? contents.join("\n\n") : source === "echoes-export" && contents.length === 1 ? contents[0] : JSON.stringify(contents.flatMap((text) => { const parsed = JSON.parse(text) as unknown; return Array.isArray(parsed) ? parsed : [parsed]; })); const result = await vaultRequest({ action: "import-private-source", passphrase, privateSource: { source, content, consent: true } }); setSummary(result.summary); setMessage(source === "editor-cut" ? `Preserved the Editor Cut and a pending macro-journey proposal (${result.editorCut?.createdRecords ?? 0} records). It did not create factual Moments or an Episode.` : `Imported ${result.import?.retained ?? 0} minimised records from ${result.import?.total ?? 0} selected source rows into the encrypted Vault.`); setSourceFiles([]); setSourceConsent(false); } catch (error) { setMessage(error instanceof Error ? error.message : "The selected private source could not be imported."); } finally { setBusy(false); } }
  function selectSideQuestFile(file: File | undefined) { if (!file) { setSideQuestFile(undefined); return; } if (!file.name.toLocaleLowerCase().endsWith(".json")) { setSideQuestFile(undefined); setSideQuestResult("Choose the Control Room JSON export, not a CSV. The CSV is a spreadsheet view and cannot preserve the tracker structure."); return; } setSideQuestFile(file); setSideQuestResult(undefined); }
  async function importSideQuest(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!sideQuestFile) return; setBusy(true); setSideQuestResult(undefined); try { if (sideQuestFile.size > 1_000_000) throw new Error("Choose a Control Room export smaller than 1 MB."); const sideQuest = JSON.parse(await sideQuestFile.text()) as unknown; const result = await vaultRequest({ action: "import-side-quest", passphrase, sideQuest }); setSummary(result.summary); setImportMarkers((current) => ({ calendarPrepared: current?.calendarPrepared ?? false, mapsPrepared: current?.mapsPrepared ?? false, mapsListPrepared: current?.mapsListPrepared ?? false, timelinePrepared: current?.timelinePrepared ?? false, youtubePrepared: current?.youtubePrepared ?? false, lastFmHistory: current?.lastFmHistory ?? false, sideQuestControlRoom: true })); setSideQuestResult("Control Room source preserved locally as source data. No tracker item was made into a life fact."); setSideQuestFile(undefined); } catch (error) { setSideQuestResult(error instanceof Error ? error.message : "The Control Room export could not be imported."); } finally { setBusy(false); } }
  async function loadSpotifySelection() { setBusy(true); setSpotifyPreviewing(true); setSpotifyPreviewMode("recent"); try { const response = await fetch("/api/connectors/spotify/selection", { cache: "no-store" }); const result = await response.json() as { error?: string; selection?: SpotifySelection }; if (!response.ok || result.error || !result.selection) throw new Error(result.error ?? "Spotify selection could not be read."); setSpotifySelection(result.selection); setSelectedPlaylists(result.selection.recommendations.map((playlist) => playlist.id)); if (!result.selection.recommendations.length) { setMessage(`Spotify connection worked: it returned ${result.selection.recentlyPlayedCount} recent play${result.selection.recentlyPlayedCount === 1 ? "" : "s"}, but no playlist playback context and ${result.selection.libraryPlaylistCount} visible library playlist${result.selection.libraryPlaylistCount === 1 ? "" : "s"} to recommend. This does not say your playlists are empty or public. No playlist was selected or imported; paste an explicit link below to preview it directly.`); return; } const basis = result.selection.selectionBasis === "recent-play-context" ? "documented playlist playback contexts" : result.selection.selectionBasis === "owned" ? "owned playlist" : result.selection.selectionBasis === "owned-collaborative" ? "owned collaborative playlist" : result.selection.selectionBasis === "library-fallback" ? "library playlist" : "eligible"; setMessage(`Spotify found ${result.selection.recommendations.length} ${basis} candidate${result.selection.recommendations.length === 1 ? "" : "s"} from ${result.selection.recentlyPlayedCount} recent plays and ${result.selection.libraryPlaylistCount} visible library playlist${result.selection.libraryPlaylistCount === 1 ? "" : "s"}. Confirm or revise before importing.`); } catch (error) { setMessage(error instanceof Error ? error.message : "Spotify selection could not be read."); } finally { setSpotifyPreviewing(false); setSpotifyPreviewMode(undefined); setBusy(false); } }
  async function useExplicitBaselinePlaylists() { const ids = [...new Set([...baselinePlaylistLinks.matchAll(/(?:open\.spotify\.com\/playlist\/|spotify:playlist:)([A-Za-z0-9]{10,64})/gu)].map((match) => match[1]))].slice(0, 4); if (!ids.length) { setSpotifyPreviewResult({ tone: "error", text: "Paste one to four Spotify playlist links (or spotify:playlist URIs) first." }); return; } setBusy(true); setSpotifyPreviewing(true); setSpotifyPreviewMode("explicit"); setSpotifyPreviewResult(undefined); try { const response = await fetch("/api/connectors/spotify/playlists", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ playlistIds: ids }) }); const result = await response.json() as { error?: string; playlists?: Array<{ id: string; name: string; tracksTotal: number; coverImageUrl?: string; spotifyUrl: string }>; unavailable?: Array<{ id: string; status: number | "unexpected" }> }; if (!response.ok || result.error || !result.playlists) throw new Error(result.error ?? "Spotify playlist previews could not be read."); const recommendations = result.playlists.map((playlist) => ({ ...playlist, recentPlayOverlap: 0 })); const unavailableSummary = result.unavailable?.length ? ` Spotify returned ${result.unavailable.map((item) => item.status === "unexpected" ? "an unexpected response" : `HTTP ${item.status}`).join(", ")} for ${result.unavailable.length} link${result.unavailable.length === 1 ? "" : "s"}.` : ""; if (!recommendations.length) { setSpotifySelection(undefined); setSelectedPlaylists([]); setSpotifyPreviewResult({ tone: "error", text: `Spotify could not read any of these four links through this connection.${unavailableSummary} Private playlists are supported, so this is a connection/API access result rather than an instruction to make them public. Reconnect Spotify and try again; no playlist was imported.` }); return; } setSpotifySelection({ recentlyPlayedCount: 0, libraryPlaylistCount: 0, selectionBasis: "explicit-baseline", recommendations }); setSelectedPlaylists(recommendations.map((playlist) => playlist.id)); setSpotifyPreviewResult({ tone: "success", text: `Previewed ${recommendations.length} explicitly chosen playlist${recommendations.length === 1 ? "" : "s"}: titles, covers and track counts are live Spotify presentation data only.${unavailableSummary} Nothing has been written to the Vault yet.` }); } catch (error) { setSpotifyPreviewResult({ tone: "error", text: error instanceof Error ? error.message : "Spotify playlist previews could not be read." }); } finally { setSpotifyPreviewing(false); setSpotifyPreviewMode(undefined); setBusy(false); } }
  async function importSpotifySelection() { setBusy(true); setSpotifyImporting(true); setSpotifyPreviewResult(undefined); try { const response = await fetch("/api/connectors/spotify/import", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ playlistIds: selectedPlaylists, consent: true }) }); const result = await response.json() as { error?: string; summary?: Summary }; if (!response.ok || result.error) throw new Error(result.error ?? "Spotify import could not run."); setSummary(result.summary); setSpotifyPreviewResult({ tone: "success", text: `Imported ${selectedPlaylists.length} confirmed Spotify playlist snapshot${selectedPlaylists.length === 1 ? "" : "s"} into the encrypted Vault. These preserve playlist metadata and additions, not a claim about why music mattered.` }); } catch (error) { setSpotifyPreviewResult({ tone: "error", text: `Spotify could not import the selected playlist${selectedPlaylists.length === 1 ? "" : "s"}. Nothing was written to the Vault. ${error instanceof Error ? error.message : "Please try again."}` }); } finally { setSpotifyImporting(false); setBusy(false); } }
  async function importLastFm(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!lastFmConsent) return; setBusy(true); setLastFmImporting(true); setLastFmResult(undefined); try { const result = await vaultRequest({ action: "import-lastfm-history", passphrase, lastFm: { username: lastFmUsername, from: new Date(`${lastFmFrom}T00:00:00.000Z`).toISOString(), to: new Date(`${lastFmTo}T23:59:59.999Z`).toISOString(), consent: true } }); const retained = result.import?.retained ?? 0; const dropped = Math.max(0, (result.import?.total ?? retained) - retained); const pages = result.import?.pagination; setSummary(result.summary); setImportMarkers((current) => ({ ...current, calendarPrepared: current?.calendarPrepared ?? false, mapsPrepared: current?.mapsPrepared ?? false, mapsListPrepared: current?.mapsListPrepared ?? false, timelinePrepared: current?.timelinePrepared ?? false, youtubePrepared: current?.youtubePrepared ?? false, lastFmHistory: true, sideQuestControlRoom: current?.sideQuestControlRoom ?? false })); setLastFmConsent(false); setLastFmResult(`Imported ${retained} timestamped scrobbles from the complete selected window (${pages?.pagesRead ?? 1} of ${pages?.totalPages ?? 1} Last.fm pages) into the encrypted Vault${dropped ? `; ${dropped} non-timestamped rows were excluded.` : "."} They establish listening time only; no meaning was inferred.`); } catch (error) { const explanation = error instanceof Error ? error.message : "The Last.fm import could not run."; setLastFmResult(explanation); } finally { setLastFmImporting(false); setBusy(false); } }
  async function importPreparedTakeout() { setBusy(true); setPreparedTakeoutImporting(true); setPreparedTakeoutResult(undefined); try { const result = await vaultRequest({ action: "import-prepared-google-takeout", passphrase }); const retained = result.import?.retained ?? 0; const sources = new Set((result.import?.sources ?? []).map((item) => item.source)); setSummary(result.summary); setImportMarkers((current) => ({ calendarPrepared: sources.has("google-takeout-calendar") || current?.calendarPrepared || false, mapsPrepared: sources.has("google-takeout-maps") || current?.mapsPrepared || false, mapsListPrepared: sources.has("google-maps-takeout-saved-list") || current?.mapsListPrepared || false, timelinePrepared: sources.has("google-timeline") || current?.timelinePrepared || false, youtubePrepared: sources.has("youtube-watch-history") || current?.youtubePrepared || false, lastFmHistory: current?.lastFmHistory ?? false, sideQuestControlRoom: current?.sideQuestControlRoom ?? false })); setPreparedTakeoutImported(retained); setPreparedTakeoutResult({ tone: "success", text: `Imported ${retained} minimised Google source rows into the encrypted Vault. They are source-recorded, pending, and non-canonical.` }); } catch (error) { setPreparedTakeoutResult({ tone: "error", text: `Prepared Google sources could not be imported. Nothing new was written. ${error instanceof Error ? error.message : "Please try again."}` }); } finally { setPreparedTakeoutImporting(false); setBusy(false); } }
  async function importPreparedSelectedMapsList() { setBusy(true); setPreparedSelectedMapsImporting(true); setPreparedSelectedMapsResult(undefined); try { const result = await vaultRequest({ action: "import-prepared-google-maps-selected-list", passphrase }); const retained = result.import?.retained ?? 0; setSummary(result.summary); setImportMarkers((current) => ({ calendarPrepared: current?.calendarPrepared ?? false, mapsPrepared: current?.mapsPrepared ?? false, mapsListPrepared: true, timelinePrepared: current?.timelinePrepared ?? false, youtubePrepared: current?.youtubePrepared ?? false, lastFmHistory: current?.lastFmHistory ?? false, sideQuestControlRoom: current?.sideQuestControlRoom ?? false })); setPreparedSelectedMapsResult({ tone: "success", text: `Encrypted ${retained} source-recorded place${retained === 1 ? "" : "s"} from the one prepared Saved list. No other Saved list was read, and list membership does not establish a visit, plan, route, priority, or meaning.` }); } catch (error) { setPreparedSelectedMapsResult({ tone: "error", text: error instanceof Error ? error.message : "The prepared selected Saved list could not be imported. Nothing was written to the Vault." }); } finally { setPreparedSelectedMapsImporting(false); setBusy(false); } }
  async function importMapsList(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!mapsListConsent || !mapsListUrl.trim() || !mapsListFile) return; setBusy(true); setMapsListImporting(true); setMapsListResult(undefined); try { if (mapsListFile.size > 4_000_000) throw new Error("Choose a Saved-list CSV smaller than 4 MB."); const result = await vaultRequest({ action: "import-google-maps-list", passphrase, googleMapsList: { url: mapsListUrl.trim(), content: await mapsListFile.text(), consent: true } }); setSummary(result.summary); setImportMarkers((current) => ({ calendarPrepared: current?.calendarPrepared ?? false, mapsPrepared: current?.mapsPrepared ?? false, mapsListPrepared: true, timelinePrepared: current?.timelinePrepared ?? false, youtubePrepared: current?.youtubePrepared ?? false, lastFmHistory: current?.lastFmHistory ?? false, sideQuestControlRoom: current?.sideQuestControlRoom ?? false })); setMapsListConsent(false); setMapsListFile(undefined); setMapsListResult({ tone: "success", text: `Imported ${result.import?.retained ?? 0} source-recorded place${result.import?.retained === 1 ? "" : "s"} from the selected Maps list and refreshed local Atlas. List membership is not a visit, future commitment, route, or priority.` }); } catch (error) { setMapsListResult({ tone: "error", text: error instanceof Error ? error.message : "The selected Maps list could not be imported. Nothing was written to the Vault." }); } finally { setMapsListImporting(false); setBusy(false); } }
  async function importEditorialDraft(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!editorialDraftConsent || !editorialDraftId) return; setBusy(true); setEditorialDraftResult(undefined); try { const result = await vaultRequest({ action: "import-private-editorial-draft", passphrase, editorialDraft: { candidateId: editorialDraftId, consent: true } }); setSummary(result.summary); setEditorialDraftConsent(false); setEditorialDraftResult({ tone: "success", text: `Encrypted “${result.editorialDraft?.title ?? "selected draft"}” as a private unpublished editorial source (${result.editorialDraft?.wordCount ?? 0} words). It did not create an Episode, Journey proposal, or public draft.` }); } catch (error) { setEditorialDraftResult({ tone: "error", text: error instanceof Error ? error.message : "The selected editorial draft could not be imported. Nothing was written to the Vault." }); } finally { setBusy(false); } }
  const lastFmNextStep = lastFmImporting ? "Import in progress: the selected window is being read and encrypted locally." : !lastFmUsername.trim() ? "Enter your Last.fm username to enable this import. It is used for this request only and is not stored in the Vault." : !lastFmConsent ? "Tick the consent box to enable this one-time import." : "Ready to import the complete selected window.";

  return <main className="research-main private-review-main"><section className="experiment-hero"><p className="eyebrow"><span /> Storywalker Vault</p><h1>A private evidence archive, not a machine that decides your life.</h1><p>Records are encrypted individually in a local SQLite database. The database holds no plain-text event content; it opens through a short-lived local session after you unlock it.</p></section><p className="live-notice" role="status">{message}</p>
    {exists === undefined ? null : <section className="notebook-card vault-card"><p className="section-kicker">{session.active ? "Vault session active" : exists ? "Unlock existing Vault" : "Create local Vault"}</p>{session.active ? <><p>Available across this browser until <b>{session.expiresAt ? new Date(session.expiresAt).toLocaleTimeString() : "the fixed expiry"}</b>.</p><div className="experiment-actions"><button type="button" className="outline-button" disabled={busy} onClick={lockSession}>Lock Vault now</button></div><p className="small-note">The passphrase is not stored in the browser. The HTTP-only session reference expires exactly 15 minutes after unlock and is not extended by use.</p></> : <><label>Vault passphrase<input type="password" autoComplete={exists ? "current-password" : "new-password"} value={passphrase} onChange={(event) => setPassphrase(event.target.value)} minLength={12} /></label><div className="experiment-actions">{exists ? <button type="button" className="primary-button" disabled={busy || passphrase.length < 12} onClick={() => run("unlock")}>Unlock Vault</button> : <button type="button" className="primary-button" disabled={busy || passphrase.length < 12} onClick={() => run("initialise")}>Create encrypted Vault</button>}</div><p className="small-note">Use a unique passphrase of 12+ characters. Losing it means the encrypted records cannot be recovered.</p></>}</section>}
    {summary ? <><section className="notebook-card vault-card"><p className="section-kicker">Vault contents</p><h2>{Object.values(summary.records).reduce((total, count) => total + count, 0)} encrypted records</h2><p className="small-note">{Object.entries(summary.records).map(([recordKind, count]) => `${count} ${recordKind}`).join(" · ") || "No records yet."}</p><button type="button" className="primary-button" disabled={busy} onClick={() => run("migrate-recovery")}>Sync recovery source ({summary.records.moment ?? 0} Moment records)</button><p className="small-note">The Moment count is the current atomised recovery source—not a total life counter. Imports, Threads, editorial cuts, and pending journey proposals are separate encrypted records. Sync is idempotent.</p></section>
      <section className="notebook-card vault-card"><p className="section-kicker">Signal Engine · one-time local intake</p><h2>Bring in selected account exports, then leave the raw files outside the Vault.</h2><p className="small-note">Spotify Extended Streaming History and Google Timeline are minimised locally before encryption. Google Timeline has no supported direct account API, so a selected Takeout/Timeline JSON is the honest one-time connection. Nothing uploads beyond this local app.</p><form onSubmit={importPrivateSource} className="vault-form"><label>Private source<select value={source} onChange={(event) => { setSource(event.target.value as PrivateSource); setSourceFiles([]); }}><option value="spotify-history">Spotify Extended Streaming History JSON</option><option value="google-timeline">Google Timeline / Takeout JSON</option><option value="echoes-export">ECHOES local JSON export</option><option value="editor-cut">Storywalker Editor Cut Markdown</option></select></label><label>{source === "editor-cut" ? "Editor Cut (.md)" : "Selected JSON export(s)"}<input type="file" accept={source === "editor-cut" ? ".md,text/markdown,text/plain" : "application/json,.json"} multiple={source !== "editor-cut"} onChange={(event) => setSourceFiles(Array.from(event.target.files ?? []))} required /></label><label className="consent-row"><input type="checkbox" checked={sourceConsent} onChange={(event) => setSourceConsent(event.target.checked)} /> I chose these local files and consent to their minimisation and encryption in this Vault.</label><button type="submit" className="primary-button" disabled={busy || !sourceFiles.length || !sourceConsent}>Import selected private source</button></form></section>
      <section className="notebook-card vault-card"><p className="section-kicker">Prepared Google Takeout</p><h2>Import the locally minimised Google sources.</h2><p className="small-note">Calendar retains title, time, location and description at your request. Maps retains labelled places only. A selected Saved Maps list retains deduplicated place titles only; its list name, URLs, comments, IDs and membership are discarded. Timeline retains selected stops and movement windows; settings and encrypted backups are never mislabelled as travel data. YouTube retains watch title, channel and timestamp where Takeout provides one. Attendees, organisers, URLs, IDs, media and account metadata stay outside the Vault.</p><button type="button" className="primary-button" disabled={busy} onClick={importPreparedTakeout}>{preparedTakeoutImporting ? "Encrypting prepared Google sources…" : preparedTakeoutImported === undefined ? "Import prepared Google sources" : "Re-import prepared Google sources"}</button>{preparedTakeoutImporting ? <p className="import-progress" role="status"><span aria-hidden="true" />Reading the prepared local derivatives and encrypting source evidence. This may take a moment; nothing becomes canon.</p> : null}{preparedTakeoutResult ? <p className={preparedTakeoutResult.tone === "error" ? "import-error" : "live-notice"} role="status">{preparedTakeoutResult.text}</p> : preparedTakeoutImported !== undefined ? <p className="live-notice" role="status">Imported {preparedTakeoutImported} minimised Google source rows into the encrypted Vault. They are source-recorded, pending, and non-canonical.</p> : importMarkers?.calendarPrepared || importMarkers?.mapsPrepared || importMarkers?.mapsListPrepared || importMarkers?.timelinePrepared || importMarkers?.youtubePrepared ? <p className="live-notice" role="status">Prepared Google sources are already encrypted: Calendar {importMarkers?.calendarPrepared ? "ready" : "not yet"} · Labeled Maps {importMarkers?.mapsPrepared ? "ready" : "not yet"} · Selected Saved list {importMarkers?.mapsListPrepared ? "ready" : "not yet"} · Timeline {importMarkers?.timelinePrepared ? "ready" : "not yet"} · YouTube {importMarkers?.youtubePrepared ? "ready" : "not yet"}.</p> : null}</section>
      <section className="notebook-card vault-card"><p className="section-kicker">Prepared selected Saved list</p><h2>Encrypt the one prepared Maps list.</h2><p className="small-note">This reads only the prepared author-selected list: 27 deduplicated place titles. It does not read any other Saved list, and retains no list name, membership, comments, URLs, IDs, or account metadata.</p><button type="button" className="primary-button" disabled={busy} onClick={importPreparedSelectedMapsList}>{preparedSelectedMapsImporting ? "Encrypting selected Saved list…" : "Import prepared selected Saved list"}</button>{preparedSelectedMapsResult ? <p className={preparedSelectedMapsResult.tone === "error" ? "import-error" : "live-notice"} role="status">{preparedSelectedMapsResult.text}</p> : importMarkers?.mapsListPrepared ? <p className="live-notice" role="status">A selected Saved list is already encrypted in this Vault and available to Atlas and Scenario Studio.</p> : null}</section>
      <section className="notebook-card vault-card"><p className="section-kicker">Google Maps Lists · selected Takeout source</p><h2>Bring one selected list into the private evidence field.</h2><p className="small-note">Google’s shared-list page is client-rendered and does not expose a stable import feed. The link remains locally prefilled only to identify the list you mean; choose the matching local CSV from Google Takeout’s Saved export. Loading this Vault page and importing the CSV do not contact Google. The URL, list ID, comments and place URLs are discarded.</p><form onSubmit={importMapsList} className="vault-form"><label>Shared Google Maps list link (local reference only)<input value={mapsListUrl} onChange={(event) => setMapsListUrl(event.target.value)} placeholder="Paste a maps.app.goo.gl or google.com/maps shared list link" maxLength={2_000} required /></label><label>Matching Google Takeout Saved CSV<input type="file" accept="text/csv,.csv" onChange={(event) => setMapsListFile(event.target.files?.[0])} required /></label><label className="consent-row"><input type="checkbox" checked={mapsListConsent} onChange={(event) => setMapsListConsent(event.target.checked)} /> I selected this one Saved CSV and consent to its minimisation and local encryption in this Vault.</label><button type="submit" className="primary-button" disabled={busy || !mapsListUrl.trim() || !mapsListFile || !mapsListConsent}>{mapsListImporting ? "Minimising and encrypting selected list…" : "Import selected Saved list"}</button></form>{mapsListImporting ? <p className="import-progress" role="status"><span aria-hidden="true" />Reading this one local CSV, dropping its identifiers and URLs, then refreshing local Atlas. Nothing becomes a visit, route, plan or canon.</p> : mapsListResult ? <p className={mapsListResult.tone === "error" ? "import-error" : "live-notice"} role="status">{mapsListResult.text}</p> : importMarkers?.mapsListPrepared ? <p className="live-notice" role="status">A minimised selected Maps list is already encrypted in this Vault and available to Atlas and Scenario Studio.</p> : null}<p className="small-note">In Takeout, select Google Maps’ Saved data, then choose only this list’s CSV here. List membership only shows that a place was saved in this selected source; it is not evidence of a visit, a future commitment, a route, priority, or meaning.</p></section>
      <section className="notebook-card vault-card"><p className="section-kicker">Private editorial candidates</p><h2>Choose a draft to preserve without publishing it.</h2><p className="small-note">This shelf lists Markdown files in the private editorial-drafts folder by filename and metadata only. The file remains unread until you select it, consent, and import. An editorial draft is not an Editor Cut, Journey proposal, Episode, or public draft.</p><button type="button" className="secondary-button" disabled={busy} onClick={() => void refreshEditorialCandidates()}>Refresh candidate shelf</button>{editorialCandidates.length ? <form onSubmit={importEditorialDraft} className="vault-form"><label>Candidate draft<select value={editorialDraftId} onChange={(event) => setEditorialDraftId(event.target.value)}>{editorialCandidates.map((candidate) => <option key={candidate.id} value={candidate.id}>{candidate.label} · {Math.ceil(candidate.bytes / 1_024)} KB</option>)}</select></label><label className="consent-row"><input type="checkbox" checked={editorialDraftConsent} onChange={(event) => setEditorialDraftConsent(event.target.checked)} /> I selected this draft and consent to encrypt it as a private unpublished editorial source.</label><button type="submit" className="primary-button" disabled={busy || !editorialDraftId || !editorialDraftConsent}>Import selected private draft</button></form> : <p className="small-note">No Markdown candidates are visible yet. Add a <code>.md</code> file under the local private editorial-drafts folder, then refresh this shelf.</p>}{editorialDraftResult ? <p className={editorialDraftResult.tone === "error" ? "import-error" : "live-notice"} role="status">{editorialDraftResult.text}</p> : null}</section>
      <section className="notebook-card vault-card">
        <p className="section-kicker">Spotify · consented account import</p>
        <h2>Choose up to four playlists, then import them once.</h2>
        <p className="small-note">This uses read-only Spotify OAuth for private/collaborative playlists and recently played tracks. When Spotify supplies a playlist playback context, it is shown as direct evidence. Otherwise, a track overlap is only a discovery cue, never a claim about where a track was played from.</p>
        {spotify?.configured ? !spotify.authorised ? <a className="primary-button" href="/api/connectors/spotify/start">Connect Spotify locally</a> : <div className="vault-form">
          <label>Explicit baseline playlist links (optional)<textarea value={baselinePlaylistLinks} onChange={(event) => setBaselinePlaylistLinks(event.target.value)} placeholder="Paste up to four open.spotify.com/playlist links, one per line" maxLength={2_000} /></label>
          <button type="button" className="outline-button" disabled={busy || !baselinePlaylistLinks.trim()} onClick={useExplicitBaselinePlaylists}>{spotifyPreviewMode === "explicit" ? "Fetching titles and covers…" : "Preview explicit playlist links"}</button>
          <button type="button" className="primary-button" disabled={busy} onClick={loadSpotifySelection}>{spotifyPreviewMode === "recent" ? "Checking recent playback contexts…" : "Find playlists from recent playback contexts"}</button>
          <p className="small-note">Private playlists are supported by this read-only connection. <a className="text-link" href="/api/connectors/spotify/start">Reconnect Spotify to refresh private playlist access</a> if a preview reports that it cannot read a link.</p>
          {spotifyPreviewing ? <p className="import-progress" role="status"><span aria-hidden="true" />{spotifyPreviewMode === "explicit" ? "Fetching the selected titles, cover art and any track counts Spotify provides." : "Checking the last 50 plays for playlist contexts Spotify actually supplied."} Nothing is being written to the Vault.</p> : null}
          {spotifyPreviewResult ? <p className={spotifyPreviewResult.tone === "error" ? "import-error" : "live-notice"} role="status">{spotifyPreviewResult.text}</p> : null}
          {spotifySelection ? <>
            <p className="small-note">{spotifySelection.selectionBasis === "recent-play-context" ? "These playlists are recorded as Spotify playback contexts in the recent window; that still does not say why they mattered." : spotifySelection.selectionBasis === "explicit-baseline" ? "These are the playlist links you explicitly chose. The cards are live browser presentation; importing writes a separate encrypted playlist snapshot. Cover-image URLs themselves are never retained." : spotifySelection.selectionBasis === "owned-collaborative" ? "Spotify did not expose a non-collaborative owned set, so these are collaborative playlists owned by this account. Check them before importing." : spotifySelection.selectionBasis === "library-fallback" ? "Spotify did not return a playlist playback context or an owned set, so these are library candidates. Check them before importing." : "Spotify supplied no playlist candidates. No playlist is selected or queued for import."}</p>
            <div className="playlist-preview-grid">{spotifySelection.recommendations.map((playlist) => <article className="playlist-preview-card" key={playlist.id}>
              {playlist.coverImageUrl ? <img className="playlist-cover" src={playlist.coverImageUrl} referrerPolicy="no-referrer" alt={`${playlist.name} playlist cover`} /> : <div className="playlist-cover playlist-cover-placeholder" aria-hidden="true">♫</div>}
              <div className="playlist-preview-meta"><div><b>{playlist.name}</b><small>{playlist.tracksTotal ? `${playlist.tracksTotal} tracks` : "Track total unavailable"}</small><small>{playlist.recentContextPlays ? `${playlist.recentContextPlays} recorded playlist-context play${playlist.recentContextPlays === 1 ? "" : "s"}` : playlist.recentPlayOverlap ? `${playlist.recentPlayOverlap} matching recent track${playlist.recentPlayOverlap === 1 ? "" : "s"} (not playback source)` : "Explicitly selected"}</small></div>{playlist.spotifyUrl ? <a href={playlist.spotifyUrl} target="_blank" rel="noreferrer">Open in Spotify</a> : null}<label className="consent-row"><input type="checkbox" checked={selectedPlaylists.includes(playlist.id)} onChange={(event) => setSelectedPlaylists((current) => event.target.checked ? [...current, playlist.id] : current.filter((id) => id !== playlist.id))} /> Import this playlist</label></div>
            </article>)}</div>
            <p className="small-note">Cover images are streamed by Spotify directly to this browser for the preview. Their URLs are not retained in the Vault. A full Spotify embed is intentionally not loaded, so the page does not add Spotify’s third-party widget or its cookies.</p>
            <p className="small-note">Importing uses the active browser-wide Vault session; the passphrase is not sent from this page.</p>
            <button type="button" className="primary-button" disabled={busy || !session.active || !selectedPlaylists.length || selectedPlaylists.length > 4} onClick={importSpotifySelection}>{spotifyImporting ? "Encrypting selected playlists…" : "Import confirmed playlists"}</button>
            {spotifyImporting ? <p className="import-progress" role="status"><span aria-hidden="true" />Reading the selected playlist items and encrypting their minimised snapshots locally. This may take a moment; nothing becomes canon.</p> : null}
          </> : null}
        </div> : <div className="small-note"><p>Create a local app in the <a href="https://developer.spotify.com/dashboard" target="_blank" rel="noreferrer">Spotify Developer Dashboard</a>, register <code>http://127.0.0.1:3001/api/connectors/spotify/callback</code> as its Redirect URI, then add its Client ID and Client Secret to ignored <code>.env.local</code> using the variable names in <code>.env.example</code>. Restart Storywalker and this button becomes the local consent connection. Do not paste either value into this browser form or this chat.</p></div>}
      </section>
      <section className="notebook-card vault-card"><p className="section-kicker">Last.fm · interim listening timeline</p><h2>Import a bounded window of timestamped scrobbles.</h2><p className="small-note">Use this while Spotify prepares its export. Last.fm contributes completed plays only; it cannot establish playlist additions, intention, or meaning. The local app reads one chosen window, minimises it immediately, and does not retain your profile URL or account name.</p>{lastFm?.configured ? <p className="small-note">Local Last.fm key detected. This is a selected-window, read-only import.</p> : <p className="small-note">No local Last.fm key is detected yet.</p>}<form onSubmit={importLastFm} className="vault-form"><label>Last.fm username<input value={lastFmUsername} onChange={(event) => setLastFmUsername(event.target.value)} placeholder="e.g. blunaoo" maxLength={64} required /></label><div className="vault-form-row"><label>From<input type="date" value={lastFmFrom} onChange={(event) => setLastFmFrom(event.target.value)} required /></label><label>To<input type="date" value={lastFmTo} onChange={(event) => setLastFmTo(event.target.value)} required /></label></div><label className="consent-row"><input type="checkbox" checked={lastFmConsent} onChange={(event) => setLastFmConsent(event.target.checked)} /> I consent to a one-time read of this Last.fm window and its minimised encryption in this Vault.</label><button type="submit" className="primary-button" aria-describedby="lastfm-import-state" disabled={busy || !lastFmUsername.trim() || !lastFmConsent}>{lastFmImporting ? "Reading and encrypting…" : "Import selected Last.fm window"}</button></form><p id="lastfm-import-state" className="import-readiness" role="status">{lastFmNextStep}</p>{lastFmImporting ? <p className="import-progress" role="status"><span aria-hidden="true" />Reading the selected window, removing non-essential fields, then encrypting it locally. This may take a moment.</p> : lastFmResult ? <p className="live-notice" role="status">{lastFmResult}</p> : importMarkers?.lastFmHistory ? <p className="live-notice" role="status">A minimised Last.fm listening source is already encrypted in this Vault.</p> : null}<p className="small-note">The key is only used by the local server and is never stored in the Vault.</p></section>
      <section className="notebook-card vault-card"><p className="section-kicker">Side Quest Control Room</p><h2>Preserve trackers as source data</h2><p className="small-note">Choose the Control Room’s full JSON export. A CSV is a spreadsheet view, not the structured tracker snapshot needed for this private import.</p><form onSubmit={importSideQuest} className="vault-form"><label>Control Room JSON export<input type="file" accept="application/json,.json" onChange={(event) => selectSideQuestFile(event.target.files?.[0])} required /></label><button type="submit" className="primary-button" disabled={busy || !sideQuestFile}>Import into encrypted Vault</button></form>{sideQuestResult ? <p className="live-notice" role="status">{sideQuestResult}</p> : importMarkers?.sideQuestControlRoom ? <p className="live-notice" role="status">A Control Room source snapshot is already encrypted in this Vault.</p> : null}</section>
      <section className="notebook-card vault-card"><p className="section-kicker">Private capture inbox</p><h2>Capture a fact without telling a story yet.</h2><form onSubmit={capture} className="vault-form"><label>Title<input value={title} onChange={(event) => setTitle(event.target.value)} required maxLength={240} placeholder="e.g. a programme deadline" /></label><div className="vault-form-row"><label>Record kind<select value={kind} onChange={(event) => setKind(event.target.value as CaptureKind)}><option value="event">Event</option><option value="work-update">Work update</option><option value="application">Application</option><option value="travel">Travel</option><option value="playlist">Playlist</option><option value="reference">Reference</option><option value="idea">Idea</option></select></label><label>Status<select value={status} onChange={(event) => setStatus(event.target.value as CaptureStatus)}><option value="happened">Happened</option><option value="planned">Planned</option><option value="applied">Applied</option><option value="not-selected">Not selected</option><option value="in-progress">In progress</option><option value="uncertain">Uncertain</option></select></label></div><label>Date or date window<input value={when} onChange={(event) => setWhen(event.target.value)} placeholder="exact if known; otherwise approximate" /></label><label>Evidence / source<textarea value={evidence} onChange={(event) => setEvidence(event.target.value)} placeholder="URL, ticket, note, or simply: author-stated in conversation" maxLength={2_000} /></label><label>Parallel threads (comma-separated)<input value={threads} onChange={(event) => setThreads(event.target.value)} placeholder="study, practice, a possible move" /></label><button type="submit" className="primary-button" disabled={busy || !title.trim()}>Save private pending evidence</button></form></section>
      <section className="notebook-card vault-card"><p className="section-kicker">Consent-first RAG · retrieval beta</p><h2>Build an evidence packet before making a connection.</h2><p className="small-note">This first layer is local, rebuildable retrieval plus transparent time/term cues. It creates context for you and a future consented editor; it does not call a model, update facts, or manufacture a Journey.</p><form onSubmit={buildEvidencePack} className="vault-form"><label>What are you trying to trace?<input value={query} onChange={(event) => setQuery(event.target.value)} minLength={3} placeholder="a programme, a song, a role…" /></label><button type="submit" className="primary-button" disabled={busy || query.trim().length < 3}>Build local evidence packet</button></form>{evidencePack ? <div className="vault-results"><p className="small-note">{evidencePack.notice}</p><ol>{evidencePack.evidence.map((result) => <li key={result.id}><b>{result.authority}</b> · {result.kind} · {result.id} · matched: {result.matchedTerms.join(", ")}<p>{result.snippet}</p></li>)}</ol>{evidencePack.connectionCandidates.length ? <><p className="section-kicker">Retrieval cues, pending your reading</p><ul>{evidencePack.connectionCandidates.map((connection) => <li key={`${connection.fromId}-${connection.toId}`}>{connection.detail}</li>)}</ul></> : null}</div> : null}<details><summary>Use simple local search instead</summary><form onSubmit={search} className="vault-form"><label>Search terms<input value={query} onChange={(event) => setQuery(event.target.value)} minLength={3} /></label><button type="submit" className="outline-button" disabled={busy || query.trim().length < 3}>Search encrypted Vault</button></form>{results.length ? <ol className="vault-results">{results.map((result) => <li key={result.id}><b>{result.kind}</b> · {result.id}<p>{result.snippet}</p></li>)}</ol> : null}</details></section></> : null}
  </main>;
}
